      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End"
      },
      "inputs": {},
      "outputs": {
        "triageCategory": { "source": "=js:$vars.emailTriage1.output.category" },
        "triagePriority": { "source": "=js:$vars.emailTriage1.output.priority" }
      }
    }
  ],
  "edges": [
    {
      "id": "edge-start-to-triage",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "emailTriage1",
      "targetPort": "input"
    },
    {
      "id": "edge-triage-to-end",
      "sourceNodeId": "emailTriage1",
      "sourcePort": "success",
      "targetNodeId": "end1",
      "targetPort": "input"
    }
  ],
